fun initializeMotor(motorName: String?): String {
    val name = requireNotNull(motorName) { "Motor name is required" }
    return "Motor initialized: $name"
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithSparkMAX() {
        Assert.assertEquals("Motor initialized: SparkMAX", initializeMotor("SparkMAX"))
    }

    @Test
    fun testWithTalonSRX() {
        Assert.assertEquals("Motor initialized: TalonSRX", initializeMotor("TalonSRX"))
    }

    @Test
    fun testWithNull() {
        try {
            initializeMotor(null)
            Assert.fail("Should have thrown an exception")
        } catch (e: IllegalArgumentException) {
            Assert.assertEquals("Motor name is required", e.message)
        }
    }
}
